        s := combat_v2_status_apply(s, p_actor, 'enraged', jsonb_build_object('value', (bm->>'enrage_x')::numeric, 'dur', (bm->>'enrage_dur')::int, 'src', p_actor), p_b)->'state';
      end if;
      return jsonb_build_object('state', s, 'draws', used);
    end if;
