    s := jsonb_set(s, epath || '{cleared}'::text[], '0'::jsonb);
  elsif k = 'enrage' then
    s := combat_v2_status_apply(s, p_actor, 'enraged', jsonb_build_object('value', (m->>'x')::numeric, 'dur', (m->>'dur')::int, 'src', p_actor), p_b)->'state';
  elsif k = 'spiral' then
    n := least((m->>'max')::int, coalesce((e->>'blocked')::int, 0));
    if n > 0 then
